import{_ as a,o as e,c as d,a2 as T}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/DATA-LIST.md","filePath":"manual-zh/DATA-LIST.md","lastUpdated":1785684581000}'),A={name:"manual-zh/DATA-LIST.md"};function o(r,t,c,n,S,_){return e(),d("div",null,[...t[0]||(t[0]=[T('<h3 id="_8-5-data-list" tabindex="-1">8.5 DATA LIST <a class="header-anchor" href="#_8-5-data-list" aria-label="Permalink to &quot;8.5 DATA LIST&quot;">​</a></h3><p><code>DATA LIST</code> 用于读取文本或二进制数据，是最基础的数据读取命令。即便是更为复杂精密的输入方法，也将 <code>DATA LIST</code> 命令作为构建模块。理解 <code>DATA LIST</code> 对于理解如何使用 PSPP 读取数据文件十分重要。</p><p><code>DATA LIST</code> 有两种主要变体，即固定格式和自由格式。此外，自由格式还有一个次要变体——列表格式，有关它与普通自由格式的差异将在下文讨论。</p><p><code>DATA LIST</code> 的每种形式都在下文详述。</p><p>参见 <a href="./GET-DATA">GET DATA</a>，该命令在 DATA LIST 的基础上提供了一些增强功能，在许多情况下可替代 DATA LIST。</p><table tabindex="0"><thead><tr><th>• DATA LIST FIXED</th><th></th><th>数据的固定列位置。</th></tr></thead><tbody><tr><td>• DATA LIST FREE</td><td></td><td>可任意使用间隔。</td></tr><tr><td>• DATA LIST LIST</td><td></td><td>每个个案必须位于单独一行。</td></tr></tbody></table>',6)])])}const D=a(A,[["render",o]]);export{l as __pageData,D as default};
